import assert from 'node:assert/strict';
import fs from 'node:fs/promises';

export async function runMotionBloomSmoke(page){
 const viewport=page.viewport(),previous=await page.evaluate(()=>({project:JSON.stringify(project),curPage,curSec,curEl,curPane,selection,secFocus,mode:NAGWEB_STORY_EDITOR.canvasMode(),timeline:NAGWEB_STORY_TIMELINE_UI.state()}));
 const visualDir='/tmp/nagweb-motion-visuals';await fs.mkdir(visualDir,{recursive:true});
 try{
  await page.evaluate(()=>{delete project.nwMotionLibrary;project.pages[0].sections=[mkSection({layout:'free',sdEnabled:false,elements:[mkEl('label',{name:'Exterior',text:'Fuera del abanico'})]})];curPage=0;curSec=0;curEl=0;selection=[];secFocus=false;saveProject();renderPane();renderPreview();history=[];future=[];});
  const before=await page.evaluate(()=>({project:JSON.stringify(project),stored:localStorage.getItem(STORE_KEY),assets:project.assets.images.length,outside:sec().elements[0]}));
  async function ready(title='Miradas que se despliegan.'){await page.waitForFunction(title=>{const f=document.querySelector('.nw-motion-dialog iframe'),d=f?.contentDocument,id=d?.querySelector('.sc')?.dataset.id;return d?.querySelector('.hd')?.textContent===title&&f.contentWindow.__NAG_SCROLL_DIRECTOR?.[id]&&[...d.querySelectorAll('.im-hov img')].every(n=>n.complete&&n.naturalWidth===480);},{},title);}
  async function poses(selector='.nw-motion-dialog iframe',gid){return page.evaluate(({selector,gid})=>{const f=document.querySelector(selector),d=f.contentDocument,id=gid||d.querySelector('.sc').dataset.id,root=gid?d.querySelector('[data-id="'+gid+'"]'):d,rt=f.contentWindow.__NAG_SCROLL_DIRECTOR[id],nodes=[...root.querySelectorAll('.im-hov')];return [0,.25,.5,1].map(p=>{rt.set(p);return nodes.map(n=>({vars:['x','y','z','rx','ry','rot','scale','opacity','blur'].map(k=>n.style.getPropertyValue('--nw-sd-'+k)),layer:+n.style.zIndex,center:n.getBoundingClientRect().left+n.getBoundingClientRect().width/2}));});},{selector,gid});}
  async function change(selector,value){await page.$eval(selector,(n,v)=>{n.value=v;n.dispatchEvent(new Event('change',{bubbles:true}));},value);}
  async function select(id){await page.click('[data-motion-library-tab="elements"]');await page.click('[data-motion-layer="'+id+'"]');}
  async function title(id,value){await select(id);await page.click('[data-motion-content="4"]');await page.keyboard.down('Control');await page.keyboard.press('A');await page.keyboard.up('Control');await page.keyboard.type(value);await page.keyboard.press('Tab');await ready(value);}
  await page.click('.tb-left [data-motion-open]');await page.click('[data-motion-template="card-bloom"]');await ready();assert.equal(await page.$eval('[data-motion-config="duration"]',n=>n.value),'10');assert.equal(await page.$eval('[data-motion-config="perspective"]',n=>n.value),'1100');assert.match(await page.$eval('.nw-motion-stage-label',n=>n.textContent),/ABANICO DE LÁMINAS/);
  const ids=await page.$$eval('[data-motion-layer]',ns=>ns.map(n=>n.dataset.motionLayer)),original=await poses();assert.deepEqual(original[0],original[3],'The loop returns to exactly the same closed pose');assert.deepEqual(original[2].map(n=>n.vars.slice(0,6)),[['-82.00px','18.00px','-120.00px','0.00deg','-20.00deg','-18.00deg'],['0.00px','-8.00px','60.00px','0.00deg','0.00deg','0.00deg'],['82.00px','18.00px','-120.00px','0.00deg','20.00deg','18.00deg']]);assert.equal(original[2][1].layer,3);assert.ok(original[2][0].center<original[2][1].center&&original[2][1].center<original[2][2].center);assert.ok(original[2][2].center-original[2][0].center>original[0][2].center-original[0][0].center+100,'Actual rendered cards spread when opened');assert.notDeepEqual(original[1][0].vars,original[0][0].vars,'Opening interpolates rather than jumping');assert.notDeepEqual(original[1][0].vars,original[2][0].vars);
  await page.$eval('[data-motion-progress]',n=>{n.value='50';n.dispatchEvent(new Event('input',{bubbles:true}));});
  const hit=await page.$eval('.nw-motion-dialog iframe',f=>{const d=f.contentDocument,n=d.querySelectorAll('.im-hov')[1],r=n.getBoundingClientRect();return d.elementFromPoint(r.left+r.width/2,r.top+r.height/2)?.closest('[data-id]')?.dataset.id;});assert.equal(hit,ids[1],'Central image is visibly in front of the overlapping edges');await (await page.$('.nw-motion-dialog')).screenshot({path:visualDir+'/bloom-desktop.png'});
  await select(ids[0]);assert.deepEqual(await page.$$eval('[data-motion-key-jump]',ns=>ns.map(n=>parseFloat(n.textContent))),[0,12,38,62,88,100]);const key=await page.$$eval('[data-motion-key-jump]',ns=>ns.find(n=>n.textContent==='38%').dataset.motionKeyJump);await page.click('[data-motion-key-jump="'+key+'"]');await change('[data-motion-key-property="z"]','-180');await title(ids[4],'Mi colección');const prepared=await poses();assert.equal(prepared[2][0].vars[2],'-150.00px');assert.deepEqual(prepared[2].slice(1).map(n=>n.vars),original[2].slice(1).map(n=>n.vars));
  await page.click('[data-motion-library-tab="library"]');await page.click('[data-motion-template="iso-focus"]');await page.click('[data-motion-template="card-bloom"]');await ready('Mi colección');assert.deepEqual((await poses()).map(ns=>ns.map(n=>n.vars)),prepared.map(ns=>ns.map(n=>n.vars)));assert.equal(await page.evaluate(()=>JSON.stringify(project)),before.project);assert.equal(await page.evaluate(()=>localStorage.getItem(STORE_KEY)),before.stored);assert.equal(await page.evaluate(()=>history.length),0);
  await page.click('[data-motion-library-name]');await page.keyboard.type('Mi abanico');await page.click('[data-motion-library-save]');const saved=await page.evaluate(()=>project.nwMotionLibrary[0]);assert.equal(saved.config.template,'card-bloom');assert.ok(saved.elements.slice(0,3).every(e=>e.sdKeyframes.length===6));await page.click('[data-motion-saved="'+saved.id+'"]');await ready('Mi colección');const copied=await page.$$eval('[data-motion-layer]',ns=>ns.map(n=>n.dataset.motionLayer));assert.ok(copied.every(id=>!ids.includes(id)));assert.deepEqual((await poses()).map(ns=>ns.map(n=>[n.vars,n.layer])),prepared.map(ns=>ns.map(n=>[n.vars,n.layer])),'Library reuse retains fan depth ordering');await page.click('[data-motion-insert-group]');
  const inserted=await page.evaluate(()=>{const group=sec().elements.find(e=>e.nwMotionInstance);return {project:JSON.stringify(project),group,members:sec().elements.filter(e=>e.parent===group.id),outside:sec().elements[0],assets:project.assets.images.length,scroll:sec().sdEnabled};});assert.equal(inserted.group.name,'Mi abanico · composición');assert.equal(inserted.group.nwMotionInstance.template,'card-bloom');assert.equal(inserted.group.nwMotionInstance.source,'time');assert.equal(inserted.scroll,false);assert.deepEqual(inserted.outside,before.outside);assert.equal(inserted.assets,before.assets+3);assert.equal(inserted.members[4].text,'Mi colección');assert.deepEqual(await page.evaluate(()=>migrate(JSON.parse(JSON.stringify(project))).nwMotionLibrary),[saved]);
  await page.evaluate(id=>NAGWEB_MOTION_LAB.edit(id),inserted.group.id);await ready('Mi colección');assert.deepEqual((await poses()).map(ns=>ns.map(n=>[n.vars,n.layer])),prepared.map(ns=>ns.map(n=>[n.vars,n.layer])));await title(copied[4],'Mi colección revisada');await page.click('[data-motion-save]');const edited=await page.evaluate(()=>JSON.stringify(project));assert.equal(await page.evaluate(()=>sec().elements.filter(e=>e.nwMotionInstance).length),1);assert.equal(await page.evaluate(id=>sec().elements.find(e=>e.id===id).text,copied[4]),'Mi colección revisada');await page.evaluate(()=>undo());assert.equal(await page.evaluate(()=>JSON.stringify(project)),inserted.project);await page.evaluate(()=>redo());assert.equal(await page.evaluate(()=>JSON.stringify(project)),edited);
  await page.evaluate(()=>{const f=document.createElement('iframe');f.id='bloom-export';f.srcdoc=generateSite(flattenPage(page()),false,false,false);document.body.append(f);});await page.waitForFunction(id=>document.querySelector('#bloom-export')?.contentWindow?.__NAG_SCROLL_DIRECTOR?.[id],{},inserted.group.id);const exported=await poses('#bloom-export',inserted.group.id);assert.deepEqual(exported.map(ns=>ns.map(n=>[n.vars,n.layer])),prepared.map(ns=>ns.map(n=>[n.vars,n.layer])),'Export evaluates the same authored fan poses and layering');
  await page.setViewport({width:390,height:844,deviceScaleFactor:1});await page.evaluate(id=>NAGWEB_MOTION_LAB.edit(id),inserted.group.id);await ready('Mi colección revisada');await page.$eval('[data-motion-progress]',n=>{n.value='50';n.dispatchEvent(new Event('input',{bubbles:true}));});assert.ok(await page.$eval('.nw-motion-dialog iframe',f=>{const nodes=[...f.contentDocument.querySelectorAll('.im-hov')];return nodes.every(n=>{const r=n.getBoundingClientRect();return r.left>=-2&&r.right<=f.contentDocument.defaultView.innerWidth+2;});}),'Open cards remain inside the compact preview');await (await page.$('.nw-motion-dialog')).screenshot({path:visualDir+'/bloom-mobile.png'});await page.click('[data-motion-close]');
  await page.emulateMediaFeatures([{name:'prefers-reduced-motion',value:'reduce'}]);await page.waitForFunction(id=>[...document.querySelector('#bloom-export').contentDocument.querySelector('[data-id="'+id+'"]').querySelectorAll('.im-hov')].every(n=>['x','y','z'].every(k=>n.style.getPropertyValue('--nw-sd-'+k)==='0.00px')),{timeout:5000},inserted.group.id);
  console.log('Abanico Motion Lab: apertura interpolada y cierre continuo, profundidad y solapamiento real, momentos editables, borradores sin escritura, Biblioteca independiente, Tiempo sin Director, misma instancia, historial/JSON, poses exportadas equivalentes, móvil y movimiento reducido OK');
 }catch(error){await page.screenshot({path:visualDir+'/bloom-failure.png'}).catch(()=>{});throw error;
 }finally{
  await page.emulateMediaFeatures([{name:'prefers-reduced-motion',value:'no-preference'}]);await page.setViewport(viewport);await page.evaluate(p=>{document.querySelector('.nw-motion-dialog').close();document.querySelector('#bloom-export')?.remove();clearTimeout(previewTimer);project=JSON.parse(p.project);curPage=p.curPage;curSec=p.curSec;curEl=p.curEl;curPane=p.curPane;selection=p.selection;secFocus=p.secFocus;history=[];future=[];NAGWEB_STORY_EDITOR.setCanvasMode(p.mode);NAGWEB_STORY_TIMELINE_UI.setState(p.timeline);saveProject();renderScenes();renderPane();renderPreview();},previous);
 }
}
